const fallbackKoMap = {"창세기":"Genesis","출애굽기":"Exodus","레위기":"Leviticus","민수기":"Numbers","신명기":"Deuteronomy","여호수아":"Joshua","사사기":"Judges","룻기":"Ruth","사무엘상":"1 Samuel","사무엘하":"2 Samuel","열왕기상":"1 Kings","열왕기하":"2 Kings","역대상":"1 Chronicles","역대하":"2 Chronicles","에스라":"Ezra","느헤미야":"Nehemiah","에스더":"Esther","욥기":"Job","시편":"Psalms","잠언":"Proverbs","전도서":"Ecclesiastes","아가":"Song of Solomon","이사야":"Isaiah","예레미야":"Jeremiah","애":"Lamentations","에스겔":"Ezekiel","다니엘":"Daniel","호세아":"Hosea","요엘":"Joel","아모스":"Amos","옵":"Obadiah","욘":"Jonah","미가":"Micah","나훔":"Nahum","하박국":"Habakkuk","스바냐":"Zephaniah","학개":"Haggai","슥":"Zechariah","말라기":"Malachi","마태복음":"Matthew","마가복음":"Mark","눅":"Luke","요한복음":"John","사도행전":"Acts","로마서":"Romans","고전":"1 Corinthians","고후":"2 Corinthians","갈":"Galatians","엡":"Ephesians","빌":"Philippians","골":"Colossians"};
const getLocalToday = () => { const o = new Date().getTimezoneOffset() * 60000; return new Date(Date.now() - o).toISOString().split('T')[0]; };
const cleanText = (t) => (t || '').replace(/|'|\x1B|\(가정\d*\)|\(개인\d*\)|\(개인\)/gi, '').trim();

const parseBibleRefExt = (r) => { 
  const m = r.replace(/\s+/g, '').match(/([가-힣0-9]+?)(\d+)(?:장|:)(?:(\d+)(?:절)?)?(?:~|-)?(?:(\d+)(?:장|:))?(?:(\d+)(?:절)?)?/); 
  if (!m) return null; const eb = fallbackKoMap[m[1]] || bookNamesKo[m[1]]; if (!eb) return null; 
  const c1 = parseInt(m[2]), v1 = m[3] ? parseInt(m[3]) : 1, c2 = m[4] ? parseInt(m[4]) : c1, v2 = m[5] ? parseInt(m[5]) : (m[3] && !m[4] ? v1 : 999); 
  return { eb, c1, v1, c2, v2, kb: m[1] }; 
};

const getSeededVerse = (d, type) => { const h = d.replace(/-/g, '').split('').reduce((a,c)=>a+parseInt(c||0),0)+parseInt(d.slice(-2)); return type === 'family' ? familyVerseCards[h % familyVerseCards.length] : newYearVerseCards[h % newYearVerseCards.length]; };
const formatVerseText = (ft) => { if (!ft || typeof ft !== 'string') return { text: '말씀을 불러오는 중입니다...', ref: '' }; const match = ft.match(/(.*?)\s*(\([^)]+\))$/); return match ? { text: match[1], ref: match[2] } : { text: ft, ref: '' }; };
const extractVideoId = (url) => { if(!url) return null; const m = url.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))((\w|-){11})/); return m ? m[1] : null; };
const isGisangogi = (d) => { const t = new Date(d).getTime(); return [{start:'2026-07-06',end:'2026-07-10'}].some(r => t >= new Date(r.start).getTime() && t <= new Date(r.end).getTime()); };
const getArr = (val, def = []) => Array.isArray(val) ? val : def;

