                  <div className="flex flex-col gap-6 mt-10 w-full max-w-sm">
                      <div onClick={() => setActiveScreen('familyPublic')} className={`${t.cardBg} p-8 rounded-3xl cursor-pointer shadow-lg border ${t.border} flex flex-col items-center justify-center hover:-translate-y-2 transition-transform`}><SmileFaceIcon className="w-12 h-12 text-blue-500 mb-4" /><h3 className={`text-lg font-black ${t.textMain}`}>공개 가정예배</h3><p className={`text-xs ${t.textSub} mt-2 text-center`}>친척 모임, 비정기 모임 등<br/>누구나 함께 참여하는 예배</p></div>
                      <div onClick={() => setActiveScreen('familyPrivateLogin')} className={`${t.cardBg} p-8 rounded-3xl cursor-pointer shadow-lg border ${t.border} flex flex-col items-center justify-center hover:-translate-y-2 transition-transform`}><HeartIcon className="w-12 h-12 text-pink-500 mb-4" /><h3 className={`text-lg font-black ${t.textMain}`}>우리 가족 가정예배</h3><p className={`text-xs ${t.textSub} mt-2 text-center`}>오직 우리 가족만 입장 가능한<br/>프라이빗 가정 예배</p></div>
                  </div>
