                           <span className={`text-[10px] whitespace-nowrap font-extrabold absolute bottom-[3px] transition-all duration-300 tracking-tight ${activeScreen === tabItem.id ? `opacity-100 ${t.textMain}` : 'opacity-0 translate-y-2'}`}>{tabItem.label}</span>
