                     <div className={`${t.appBg} p-5 rounded-2xl border ${t.border}`}><h4 className={`font-extrabold ${t.textMain} text-sm mb-2 flex items-center gap-1`}>📖 상세 해석 및 어원</h4><p className={`text-sm ${t.textSub} leading-relaxed whitespace-pre-wrap`}>{mLocal.word.desc}</p></div>
